WITH filing_rank AS (SELECT f.*,ROW_NUMBER() OVER(PARTITION BY f.cik,f.report_period ORDER BY f.is_amendment DESC,f.filed_date DESC,f.accession DESC) period_rank FROM filings f WHERE f.form_type IN ('13F-HR','13F-HR/A')),snapshots AS (SELECT f.cik,f.report_period,f.accession,h.name_of_issuer,h.title_of_class,h.cusip,h.value_usd,h.shares_or_principal FROM filing_rank f JOIN holdings h USING(accession) WHERE period_rank=1),ranked AS (SELECT *,LAG(value_usd) OVER(PARTITION BY cik,cusip ORDER BY report_period) prior_value_usd,LAG(shares_or_principal) OVER(PARTITION BY cik,cusip ORDER BY report_period) prior_shares FROM snapshots),latest AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY cik,cusip ORDER BY report_period DESC) rn FROM ranked) SELECT cik,report_period,accession,name_of_issuer,title_of_class,cusip,prior_value_usd,value_usd,value_usd-COALESCE(prior_value_usd,0) value_change_usd,prior_shares,shares_or_principal current_shares,shares_or_principal-COALESCE(prior_shares,0) share_change,CASE WHEN prior_shares IS NULL THEN 'NEW' WHEN shares_or_principal=0 THEN 'SOLD_OUT' WHEN shares_or_principal>prior_shares THEN 'INCREASED' WHEN shares_or_principal<prior_shares THEN 'DECREASED' ELSE 'UNCHANGED' END action FROM latest WHERE rn=1 ORDER BY ABS(value_usd-COALESCE(prior_value_usd,0)) DESC;
